# build_empresas.py — % de compraventas de vivienda con comprador persona jurídica (empresa), Castilla y León y España.
# Entrada: texto de los anuarios de la Estadística Registral Inmobiliaria (Colegio de Registradores), ERI_Anuario_AAAA.txt,
# extraído de los PDF publicados en registradores.org. No hay dato provincial público; se usa el de Castilla y León.
# Uso: python build_empresas.py <carpeta_txt> <salida.json>
import json, os, re, sys

D, OUT = sys.argv[1], sys.argv[2]
CODE = open(os.path.abspath(__file__), encoding='utf-8').read()


def pct(s):
    return float(s.replace(',', '.'))


rows = {}
for f in sorted(os.listdir(D)):
    m = re.match(r'ERI_Anuario_(\d{4})\.txt$', f)
    if not m:
        continue
    y = int(m.group(1))
    t = open(os.path.join(D, f), encoding='utf-8', errors='replace').read().split('\n')
    for i, l in enumerate(t):
        # Tabla "compraventas de viviendas por tipo de adquirente": cabecera con Personas físicas y Personas jurídicas
        if i > 2500 and re.search(r'Personas?\s+F[ií]sicas.*Personas\s+Jur[ií]dicas', l, re.I):
            for j in range(i + 1, min(i + 40, len(t))):
                c = re.match(r'\s*CASTILLA Y LE[OÓ]N\s+([\d,]+)\s*%\s+(?:(-?[\d,]+)\s+)?([\d,]+)\s*%(?:\s+(-?[\d,]+))?', t[j], re.I)
                if c:
                    r = {'anio': y, 'pct_empresas_cyl': pct(c.group(3))}
                    if c.group(2) is not None:  # desde 2022 la tabla trae la variación anual (pp) de personas físicas
                        r['var_pp_fisicas'] = pct(c.group(2))
                    rows[y] = r
                    break
            if y in rows:
                break
    if y not in rows:
        # 2017: la tabla no se extrajo bien del PDF; el texto da el % de personas físicas de Castilla y León
        for l in t:
            c = re.search(r'Castilla y León \(([\d,]+)%\)', l)
            if c and 'físicas' in ' '.join(t).lower() and pct(c.group(1)) > 80:
                rows[y] = {'anio': y, 'pct_empresas_cyl': round(100 - pct(c.group(1)), 2), 'nota': 'calculado como 100 − % personas físicas del texto'}
                break
# 2021 no tiene anuario descargado: sale de 2022 menos la variación anual que publica el anuario de 2022
if 2022 in rows and 2021 not in rows and 'var_pp_fisicas' in rows[2022]:
    rows[2021] = {'anio': 2021, 'pct_empresas_cyl': round(rows[2022]['pct_empresas_cyl'] + rows[2022]['var_pp_fisicas'], 2),
                  'nota': 'calculado con el anuario de 2022 (dato 2022 + variación anual)'}
out = [rows[y] for y in sorted(rows)]
json.dump({'rows': out, 'meta': [
    {'label': 'build_empresas.py', 'value': CODE, 'type': 'code', 'lang': 'python'},
    {'label': 'Fuentes', 'value': 'Colegio de Registradores, Estadística Registral Inmobiliaria, anuarios 2015–2025 '
                                  '(https://www.registradores.org/actualidad/portal-estadistico-registral/estadisticas-de-propiedad). '
                                  'Tabla de distribución de compraventas de vivienda por tipo de adquirente, por comunidad autónoma.'},
    {'label': 'Notas', 'value': 'Dato de Castilla y León, no de la provincia de León, que no se publica.'}]},
    open(OUT, 'w', encoding='utf-8'), ensure_ascii=False)
for r in out:
    print(r)
